        // Run ASM
        run_asm(snes);
        Snap asm_post; snap_take(&asm_post, snes);

        // Restore and run C
        snap_restore(&pre, snes);
        snes->cpu->dp = 0x0600;
        snes->cpu->db = 0x00;
        snes->cpu->mf = true;
        snes->cpu->xf = false;
